PAYLOAD: Dict[str, Any] = json.loads(PAYLOAD_JSON)

PROBLEM_FAMILIES = PAYLOAD["problem_families"]
DECISION_TREES = PAYLOAD["decision_trees"]
STATEMENT_PATTERNS = PAYLOAD["statement_patterns"]
COMMON_TRAPS = PAYLOAD["common_traps"]
INTERVIEW_STRATEGIES = PAYLOAD["interview_strategies"]
MAPPED_EXERCISES = PAYLOAD["mapped_exercises"]
DECISION_MATRIX = PAYLOAD["problem_formula_strategy_error_matrix"]


def export_excel_only_decision_framework_payload() -> Dict[str, Any]:
    return PAYLOAD


def contains_banned_scope_text() -> bool:
    banned_terms = ["Power Query", "powerquery", "solucao_powerquery", "Table.", "codigo_m", "exemplos M"]
    text = json.dumps(PAYLOAD, ensure_ascii=False)
    return any(term in text for term in banned_terms)


def validate_payload() -> List[Dict[str, Any]]:
    checks = [
        {
            "regra": "Escopo somente Excel",
            "status": "OK" if not contains_banned_scope_text() else "FALHA",
            "evidencia": "Sem termos de escopo removido no payload",
            "criticidade": "Crítica",
        },
        {
            "regra": "Árvores de decisão >= 200",
            "status": "OK" if len(DECISION_TREES) >= MIN_DECISION_TREES else "FALHA",
            "evidencia": str(len(DECISION_TREES)),
            "criticidade": "Crítica",
        },
        {
            "regra": "Padrões de enunciados >= 100",
            "status": "OK" if len(STATEMENT_PATTERNS) >= MIN_STATEMENT_PATTERNS else "FALHA",
            "evidencia": str(len(STATEMENT_PATTERNS)),
            "criticidade": "Crítica",
        },
        {
            "regra": "Armadilhas comuns >= 100",
            "status": "OK" if len(COMMON_TRAPS) >= MIN_TRAPS else "FALHA",
            "evidencia": str(len(COMMON_TRAPS)),
            "criticidade": "Crítica",
        },
        {
            "regra": "Estratégias de entrevista >= 100",
            "status": "OK" if len(INTERVIEW_STRATEGIES) >= MIN_INTERVIEW_STRATEGIES else "FALHA",
            "evidencia": str(len(INTERVIEW_STRATEGIES)),
            "criticidade": "Crítica",
        },
        {
            "regra": "Exercícios conectados ao mapa >= 100",
            "status": "OK" if len(MAPPED_EXERCISES) >= MIN_MAPPED_EXERCISES else "FALHA",
            "evidencia": str(len(MAPPED_EXERCISES)),
            "criticidade": "Crítica",
        },
        {
            "regra": "Matriz problema-fórmula-estratégia-erro >= 100",
            "status": "OK" if len(DECISION_MATRIX) >= MIN_MATRIX_ROWS else "FALHA",
            "evidencia": str(len(DECISION_MATRIX)),
            "criticidade": "Crítica",
        },
        {
            "regra": "Todos exercícios têm vínculos ao mapa",
            "status": "OK" if all(e.get("arvore_decisao_id") and e.get("padrao_enunciado_id") and e.get("armadilha_id") for e in MAPPED_EXERCISES) else "FALHA",
            "evidencia": "Campos de vínculo presentes",
            "criticidade": "Alta",
        },
        {
            "regra": "Streamlit opcional",
            "status": "OK",
            "evidencia": "Import tratado com ModuleNotFoundError",
            "criticidade": "Alta",
        },
    ]
    return checks


def mental_map_text() -> str:
    return """ENUNCIADO
│
├─ 1. Identifique o verbo principal
│   ├─ limpar/padronizar → Texto
│   ├─ buscar/retornar → Busca
│   ├─ somar/contar/média → Agregação
│   ├─ classificar/status → Condicional
│   ├─ listar/filtrar/top → Matriz dinâmica
│   ├─ prazo/vencimento → Datas
│   ├─ contém/padrão → Coringas
│   ├─ validar/auditar → Auditoria
│   ├─ média/correlação/desvio → Estatística
│   └─ lentidão/modelo → Performance
│
├─ 2. Defina a saída
│   ├─ Uma célula → fórmula direta
│   ├─ Uma coluna → tabela estruturada
│   ├─ Uma lista → FILTRO/ÚNICO/CLASSIFICAR
│   ├─ Um resumo → SOMASES/CONT.SES/MÉDIASES
│   └─ Um diagnóstico → LET/SEERRO/validação
│
├─ 3. Identifique o risco
│   ├─ Texto sujo
│   ├─ Chave ausente
│   ├─ Critério incompleto
│   ├─ Faixa ambígua
│   ├─ Dado vazio
│   └─ Fórmula difícil de explicar
│
└─ 4. Entregue a solução
    ├─ Diagnóstico do tipo de problema
    ├─ Fórmula escolhida
    ├─ Justificativa
    ├─ Validação
    └─ Erro comum evitado
"""


def recommend_from_statement(statement: str) -> Dict[str, Any]:
    text = statement.lower()
    scored = []
    for fam in PROBLEM_FAMILIES:
        score = sum(1 for verb in fam["verbos"] if verb.lower() in text)
        score += sum(1 for formula in fam["formulas"] if formula.lower() in text)
        scored.append((score, fam))
    scored.sort(key=lambda x: x[0], reverse=True)
    best = scored[0][1]
    if scored[0][0] == 0:
        best = next(f for f in PROBLEM_FAMILIES if f["id"] == "P08")
    related_exercises = [e for e in MAPPED_EXERCISES if e["familia_id"] == best["id"]][:10]
    related_matrix = [m for m in DECISION_MATRIX if m["problema"] == best["nome"]][:10]
    return {
        "tipo_recomendado": best["nome"],
        "formulas": best["formulas"],
        "estrategia": best["estrategia"],
        "erro_comum": best["erro"],
        "saida_esperada": best["saida"],
        "exercicios_relacionados": [e["id"] for e in related_exercises],
        "matriz_relacionada": related_matrix,
    }


def to_dataframe(rows: List[Dict[str, Any]]):
    if pd is None:
        return rows
    return pd.DataFrame(rows)


def filter_rows(rows: List[Dict[str, Any]], search: str = "", key: str = "", value: str = "Todos") -> List[Dict[str, Any]]:
    result = []
    term = search.lower().strip()
    for row in rows:
        if key and value != "Todos" and row.get(key) != value:
            continue
        if term and term not in json.dumps(row, ensure_ascii=False).lower():
            continue
        result.append(row)
    return result


def print_validation_report() -> None:
    checks = validate_payload()
    failures = sum(1 for c in checks if c["status"] == "FALHA")
    print("=" * 78)
    print("VALIDAÇÃO DO BLOCO 10 — EXCEL ONLY DECISION FRAMEWORK V14")
    print("=" * 78)
    print(f"Bloco: {BLOCK_NAME}")
    print(f"Versão: {APP_VERSION}")
    print(f"Status: {BLOCK_STATUS}")
    print(f"Streamlit disponível: {STREAMLIT_AVAILABLE}")
    print(f"Famílias de problema: {len(PROBLEM_FAMILIES)}")
    print(f"Árvores de decisão: {len(DECISION_TREES)}")
    print(f"Padrões de enunciados: {len(STATEMENT_PATTERNS)}")
    print(f"Armadilhas comuns: {len(COMMON_TRAPS)}")
    print(f"Estratégias de entrevista: {len(INTERVIEW_STRATEGIES)}")
    print(f"Exercícios conectados: {len(MAPPED_EXERCISES)}")
    print(f"Linhas da matriz: {len(DECISION_MATRIX)}")
    print(f"Falhas core: {failures}")
    print(f"Aprovado core: {failures == 0}")
    print("-" * 78)
    for c in checks:
        print(f"[{c['status']}] {c['regra']} — {c['evidencia']}")
    print("-" * 78)
    print(mental_map_text())
    print("=" * 78)


CUSTOM_CSS = """
<style>
.block-container { max-width: 1600px !important; padding-top: 1rem !important; padding-left: 1.25rem !important; padding-right: 1.25rem !important; }
.stTabs [data-baseweb="tab-list"] { gap: 0.25rem; flex-wrap: wrap; }
.stTabs [data-baseweb="tab"] { height: auto; min-height: 38px; white-space: normal; padding: 8px 12px; }
pre, code { white-space: pre-wrap !important; word-break: break-word !important; overflow-wrap: anywhere !important; font-size: 0.78rem !important; }
</style>
"""


def render_table(title: str, rows: List[Dict[str, Any]], height: int = 420) -> None:
    st.subheader(title)
    if pd is None:
        st.write(rows)
        return
    st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True, height=height)


def render_app() -> None:
    if not STREAMLIT_AVAILABLE:
        raise RuntimeError("Streamlit não instalado. Use print_validation_report().")

    st.set_page_config(page_title="Excel Decision Framework V14", page_icon="🧠", layout="wide")
    st.markdown(CUSTOM_CSS, unsafe_allow_html=True)
    st.title("Excel Only Decision Framework V14")
    st.caption("Mapa mental · Árvores de decisão · Padrões de enunciado · Fórmulas · Estratégias de entrevista")

    with st.sidebar:
        page = st.radio(
            "Seção",
            ["Dashboard", "Mapa Mental", "Árvores", "Padrões", "Armadilhas", "Entrevista", "Exercícios", "Matriz", "Diagnóstico", "Auditoria"],
            index=0,
        )
        search = st.text_input("Buscar", "")
        tipo = st.selectbox("Tipo de problema", ["Todos"] + [f["nome"] for f in PROBLEM_FAMILIES])

    if page == "Dashboard":
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Árvores", len(DECISION_TREES))
        c2.metric("Padrões", len(STATEMENT_PATTERNS))
        c3.metric("Exercícios", len(MAPPED_EXERCISES))
        c4.metric("Matriz", len(DECISION_MATRIX))
        render_table("Famílias de problema", PROBLEM_FAMILIES)

    elif page == "Mapa Mental":
        st.code(mental_map_text(), language="text")

    elif page == "Árvores":
        rows = filter_rows(DECISION_TREES, search, "tipo_problema", tipo)
        render_table("Árvores de decisão", rows, 520)

    elif page == "Padrões":
        rows = filter_rows(STATEMENT_PATTERNS, search, "tipo_problema", tipo)
        render_table("Padrões de enunciado", rows, 520)

    elif page == "Armadilhas":
        rows = filter_rows(COMMON_TRAPS, search, "tipo_problema", tipo)
        render_table("Armadilhas comuns", rows, 520)

    elif page == "Entrevista":
        rows = filter_rows(INTERVIEW_STRATEGIES, search, "tipo_problema", tipo)
        render_table("Estratégias de entrevista", rows, 520)

    elif page == "Exercícios":
        rows = filter_rows(MAPPED_EXERCISES, search, "tipo_problema", tipo)
        render_table("Exercícios conectados ao mapa", rows, 520)
        for ex in rows[:30]:
            with st.expander(f"{ex['id']} · {ex['tipo_problema']} · {ex['nivel']}", expanded=False):
                st.markdown("**Enunciado**")
                st.write(ex["enunciado"])
                st.markdown("**Diagnóstico**")
                st.write(ex["diagnostico"])
                st.markdown("**Fórmula recomendada**")
                st.code(ex["formula_recomendada"], language="text")
                st.markdown("**Raciocínio de entrevista**")
                st.write(ex["raciocinio_entrevista"])
                st.markdown("**Passo a passo**")
                for step in ex["passo_a_passo"]:
                    st.write(step)

    elif page == "Matriz":
        rows = filter_rows(DECISION_MATRIX, search, "problema", tipo)
        render_table("Problema → Fórmula → Estratégia → Erro comum", rows, 560)

    elif page == "Diagnóstico":
        statement = st.text_area("Cole o enunciado", height=160)
        if statement:
            st.json(recommend_from_statement(statement))

    elif page == "Auditoria":
        render_table("Checklist", validate_payload())


if __name__ == "__main__":
    if STREAMLIT_AVAILABLE:
        try:
            render_app()
        except Exception as exc:
            print_validation_report()
            print(f"AVISO: UI Streamlit não renderizada. Detalhe: {exc}")
    else:
        print_validation_report()
